 "content": "def transform(grid):
    """Replace each nonzero cell by a 3x3 tile shaped like input's zero mask."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    empty_pattern = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    out = [[0 for _ in range(w * 3)] for _ in range(h * 3)]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                for dr, dc in empty_pattern:
                    out[r * 3 + dr][c * 3 + dc] = value
    return out

